        for neighbor, weight in graph[node]:
            if distances[node] != float('inf') and distances[node] + weight < distances[neighbor]:
                return (float('inf'), [])  # Negative cycle detected

    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]
    path.reverse()

    if distances[end] == float('inf'):
        return (float('inf'), [])

    return (distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implement the Floyd-Warshall algorithm for finding shortest paths in a weighted directed graph.
    This algorithm uses dynamic programming to compute the shortest paths between all pairs of nodes.
    """
    nodes = list(graph.keys())
    distance = {node: {n: float('inf') for n in nodes} for node in nodes}
    next_node = {node: {n: None for n in nodes} for node in nodes}

    # Initialize distances based on direct edges
    for node in nodes:
        distance[node][node] = 0
        for neighbor, weight in graph[node]:
            distance[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    # Floyd-Warshall algorithm
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if distance[i][j] > distance[i][k] + distance[k][j]:
                    distance[i][j] = distance[i][k] + distance[k][j]
                    next_node[i][j] = next_node[i][k]

    # Reconstructing the shortest path
    if distance[start][end] == float('inf'):
        return (float('inf'), [])

    path = []
    current = start
    while current is not None:
        path.append(current)
        if current == end:
            break
        current = next_node[current][end]

    return (distance[start][end], path)

